Section LE64FT.
  Variables (ra sp gp tp x5 x6 x7 x8 x9 x10 x11 x12 x13 x14 x15 x16 x17 x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29
             x30 x31 : word)
            (F : bvmap 5 word) (fc : bv 32) (m : fmem) (S : Z) (bs : list Z) (POST : machine_state -> Prop).
  Hypothesis SRC : bytes_at psegs m S (map (Z_to_bv 8) bs).
  Hypothesis BY : Forall (fun c => 0 <= c < 256) bs.

  Ltac ldb0 p k :=
    let RX := fresh "RX" in
    pose proof (src_rd psegs m S bs (p + k) SRC ltac:(lia)) as RX;
    rewrite ?Z.add_assoc, ?Z.add_0_r in RX;
    zstep; cbv beta; clear RX.

  (* [comment removed for export] *)
  Lemma ft_ld1 : forall (p : Z) (y8 y9 y18 y21 y22 y30 : word),
    0 <= p -> p + 8 <= zlen bs ->
    (forall (z8 z9 z18 z21 z22 : word),
       evt psegs POST (MS (mkR ra sp gp tp x5 x6 x7 z8 z9 x10 (Z_to_bv 64 (S + p)) x12 x13 x14 x15 x16 x17 z18 x19 x20 z21 z22
                               x23 x24 x25 x26 x27 x28 x29 (Z_to_bv 64 (le64v bs p)) x31)
                          F (Z_to_bv 64 0x1c9cc) fc None m (seg_rom psegs))) ->
    evt psegs POST (MS (mkR ra sp gp tp x5 x6 x7 y8 y9 x10 (Z_to_bv 64 (S + p)) x12 x13 x14 x15 x16 x17 y18 x19 x20 y21 y22
                            x23 x24 x25 x26 x27 x28 x29 y30 x31)
                       F (Z_to_bv 64 0x1c974) fc None m (seg_rom psegs)).
